  c.drone_cap_check += 1; if (c.drone_cap_check >= 999) c.drone_cap_check = 0;
  c.counter_update_power += 60 * s.dt / s.statGameSpeed;
  if (c.counter_update_power >= (opt.powerEvery ?? 1e9)) { s.dock_power = power(s); c.counter_update_power = 0; }
  if (c.buffer_before_offline_kicks_in > 0) c.buffer_before_offline_kicks_in -= 60 * s.dt;
  s.fishTickCounter += 60 * s.dt / s.statGameSpeed;
  if (s.fish_offline_ticks_banked > 0 && c.buffer_before_offline_kicks_in <= 1) {
    const k = Math.min(s.fish_offline_ticks_banked, 1);
    s.fishTickCounter += s.statFishTickSpeed * k; s.fish_offline_ticks_banked -= k;
  }
  const ticks = [];
  while (s.fishTickCounter >= s.statFishTickSpeed) {
    let n = 1;
    for (const [k, m] of [['statFishDoubleTickChance', 2], ['statFishTripleTickChance', 3], ['statFish5xTickChance', 5]]) if (chance(G[opt.tg ?? 31], s[k] * 10, 1000)) n *= m;
    const r = tick(s, n, rb, G, { cap: 9.99 });
